using OcctSharp.ConstructionWorkspaces;
using OcctSharp.MeshingWorkspaces;
using OcctSharp.MeshProximity;
namespace OcctSharp.Tests.Shared;
internal static class BatchBOMeshProximityWorkflow {
 internal static Shape Face(double z=0,int grid=1){using var result=ParameterizedConstruction.AnalyticFace(AnalyticConstructionSurface.Plane,new(new(0,0,z),new(0,0,1),new(1,0,0)),0,4,0,4);using var shape=result.CopyShape();using var meshed=ControlledMeshing.Run(shape,new(Deflection:.1));if(!meshed.IsDone||!meshed.HasCompleteTriangulation)throw new InvalidOperationException("BO controlled BL face meshing failed.");using var copied=meshed.CopyShape();if(grid==1)return MeshTopology.CopyWithTriangulation(copied);return MeshTopology.ReplaceTriangulation(copied,0,Grid(z,grid));}
 internal static AuthoredMesh Grid(double z,int count){var nodes=new List<GpPoint>();for(int y=0;y<=count;++y)for(int x=0;x<=count;++x)nodes.Add(new(4.0*x/count,4.0*y/count,z));var triangles=new List<MeshTriangle>();for(int y=0;y<count;++y)for(int x=0;x<count;++x){int a=y*(count+1)+x,b=a+1,c=a+count+1,d=c+1;triangles.Add(new(a,b,d));triangles.Add(new(a,d,c));}return new(nodes,triangles);}
 internal static void Run(){using var first=Face();using var same=Face();using var upper=Face(2);using var overlap=MeshProximityComputations.Compute(first,same);if(!overlap.IsDone||overlap.Pairs.Count!=1||overlap.Pairs[0]!=new MeshOverlapPair(0,0)||overlap.LayerThickness is not null||overlap.Reference is not null)throw new InvalidOperationException("BO exact zero-based overlap relation failed.");using var separated=MeshProximityComputations.Compute(first,upper,new(Tolerance:1));if(!separated.WasPerformed||separated.IsDone||separated.Pairs.Count!=0)throw new InvalidOperationException("BO finite tolerance separation failed.");using var proximity=MeshProximityComputations.Compute(first,upper,new(Mode:MeshProximityMode.LayerThickness));if(!proximity.IsDone||proximity.LayerThickness is not {} value||Math.Abs(value-2)>1e-6||proximity.Reference is null||proximity.Pairs.Count!=0||!proximity.IsApproximate||proximity.CertifiedGeometricErrorBound is not null)throw new InvalidOperationException("BO approximate layer-thickness mode failed.");var reference=proximity.Reference;if(Math.Abs(BatchBMFiniteExtremaWorkflow.Distance(reference.FirstPoint,reference.SecondPoint)-value)>1e-6)throw new InvalidOperationException("BO native proximity reference coupling failed.");first.Dispose();upper.Dispose();using var face=proximity.CopyFace(0,0);proximity.Dispose();if(!face.IsValid||MeshTopology.SnapshotExisting(face).Mesh.Triangles.Count!=2)throw new InvalidOperationException("BO result face/mesh independent lifetime failed.");}
}
